python
def ribbonRunsPositiveInkInvoice(line):
    a=line
    out=[]
    i=0
    while i<len(a):
        j=i+1
        while j<len(a) and a[j]==a[i]: j+=1
        out.append(j-i)
        i=j
    return sum(x for x in out if x>0)


java
class Solution {
  public int ribbonRunsPositiveInkInvoice(String line) {
    String a=line; List<Integer> out=new ArrayList<>();
    {for(int i=0;i<a.length();){int j=i+1;while(j<a.length()&&a.charAt(j)==a.charAt(i))j++;out.add(j-i);i=j;}}
    int answer=0;for(int x:out)if(x>0)answer+=x;return answer;
  }
}
